  const scripts = Array.from(document.querySelectorAll('script')).filter(script => script.textContent.includes('caption') || script.textContent.includes('timedtext'));
  let urls = [];
  scripts.forEach(script => {
    const matches = script.textContent.match(/https?:\/\/[^"\s]+\.xml/g);
    if (matches) urls.push(...matches);
  });
  return urls.slice(0, 5);
}"}

