{"function": "() => {
  // Find the transcript panel
  const panel = document.querySelector('ytd-transcript-body-renderer, ytd-transcript-segment-list-renderer');
  if (!panel) {
    // fallback: look for buttons with timestamps and text in the transcript section
    const transcriptSection = document.querySelector('[aria-label="Transcript"]');
    if (transcriptSection) {
      const buttons = Array.from(transcriptSection.querySelectorAll('button')).filter(btn => btn.innerText.match(/^\d+:\d+/));
      return buttons.map(btn => btn.innerText.trim());
    }
  }
  // Get all segment elements
  const segments = panel ? panel.querySelectorAll('ytd-transcript-segment-renderer') : [];
  const result = [];
  segments.forEach(seg => {
    const time = seg.querySelector('.segment-timestamp')?.innerText.trim();
    const text = seg.querySelector('.segment-text')?.innerText.trim();
    result.push(`${time}: ${text}`);
  });
  return result;
}"}

